@prefix acttype: <https://w3id.org/ogc/rim/activity-type/> .
@prefix geoproc: <https://w3id.org/ogc/rim/geoprocessing/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:detail [ a sh:ValidationResult ;
                    sh:focusNode <https://geolabs.github.io/bblocks-generic-profiles/def/activity-type/fixture-geoprocessing-without-spatial-entity> ;
                    sh:resultMessage "Node <https://geolabs.github.io/bblocks-generic-profiles/def/activity-type/fixture-geoprocessing-without-spatial-entity> must conform to one or more shapes in [ sh:not [ sh:class acttype:ActivityType ] ] , geoproc:GeoprocessingActivityTypeShape" ;
                    sh:resultSeverity sh:Violation ;
                    sh:sourceConstraintComponent sh:OrConstraintComponent ;
                    sh:sourceShape [ sh:or ( [ sh:not [ sh:class acttype:ActivityType ] ] geoproc:GeoprocessingActivityTypeShape ) ] ;
                    sh:value <https://geolabs.github.io/bblocks-generic-profiles/def/activity-type/fixture-geoprocessing-without-spatial-entity> ] ;
            sh:focusNode geoproc:GeoprocessingActivityType ;
            sh:resultMessage "Value does not conform to Shape [ sh:or ( [ sh:not [ sh:class acttype:ActivityType ] ] geoproc:GeoprocessingActivityTypeShape ) ]. See details for more information." ;
            sh:resultPath [ sh:oneOrMorePath [ sh:inversePath rdfs:subClassOf ] ] ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:NodeConstraintComponent ;
            sh:sourceShape [ sh:node [ sh:or ( [ sh:not [ sh:class acttype:ActivityType ] ] geoproc:GeoprocessingActivityTypeShape ) ] ;
                    sh:path [ sh:oneOrMorePath [ sh:inversePath rdfs:subClassOf ] ] ] ;
            sh:value <https://geolabs.github.io/bblocks-generic-profiles/def/activity-type/fixture-geoprocessing-without-spatial-entity> ] .
